package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import android.net.Uri;import org.json.*;import java.util.*;
/** Actual WebView taps/long touch, native save bridge, synthetic record and existing local image. */
public final class ImageSaveFlowTest extends DocumentEditorTest {
 final List<Uri> exports=new ArrayList<>();
 void preview()throws Exception{click("#doc-body img");until("!!document.querySelector('#doc-image-viewer img')&&document.querySelector('#doc-image-viewer img').naturalWidth>0&&!document.querySelector('#doc-image-save').disabled");}
 void holdImage()throws Exception{JSONArray p=new JSONArray(h.js("(()=>{const r=document.querySelector('#doc-image-viewer img').getBoundingClientRect();return [(r.left+r.right)/2,(r.top+r.bottom)/2,innerWidth]})()"));float x=(float)(p.getDouble(0)*h.web.getWidth()/p.getDouble(2)),y=(float)(p.getDouble(1)*h.web.getWidth()/p.getDouble(2));long down=SystemClock.uptimeMillis();runOnMainSync(()->{android.view.MotionEvent event=android.view.MotionEvent.obtain(down,down,0,x,y,0);h.web.dispatchTouchEvent(event);event.recycle();});Thread.sleep(800);runOnMainSync(()->{android.view.MotionEvent event=android.view.MotionEvent.obtain(down,SystemClock.uptimeMillis(),1,x,y,0);h.web.dispatchTouchEvent(event);event.recycle();});}
 @Override public void onStart(){Bundle result=new Bundle();try{
  h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");JSONObject img=(JSONObject)h.call("storeRecordImage",new JSONObject().put("data",image()).put("name","合成AI插画.jpg"));
  h.js("window.__saveNative=LifeNative;window.__saves=[];window.__savedUris=[];window.__failSave=false;window.__holdSave=false;window.__saveReply=nativeReply;nativeReply=r=>{if(r.data?.saved&&r.data?.uri)__savedUris.push(r.data.uri);__saveReply(r)};LifeNative={call:(a,p,id)=>{if(a==='saveRecordImage'){__saves.push(JSON.parse(p));if(__failSave){nativeReply({id,error:'合成存储空间不足，请重试'});return;}if(__holdSave){window.__deferredSave={a,p,id};return;}}__saveNative.call(a,p,id)}}");
  open("learning");input("图片保存验证","这段正文与图片保存无关，不应被修改。");h.js("RecordEditor.image("+img+")");until("!!document.querySelector('#doc-body img')");h.js("window.__beforeImageSave=DocumentRich.serialize(document.querySelector('#doc-body'))");preview();
  check(h.js("(()=>{const b=document.querySelector('#doc-image-save'),r=b.getBoundingClientRect(),f=b.closest('footer');return r.width>=44&&r.height>=44&&r.bottom<=innerHeight+1&&f.scrollWidth<=f.clientWidth+1})()").equals("true"),"Save action is visible, touch-sized and fits phone toolbar");
  holdImage();until("!document.querySelector('#doc-image-menu').hidden");check(h.js("__saves.length===0").equals("true"),"Real long press opens menu without saving or sending an AI request");h.screenshot("image-long-press-save.png");
  h.js("RecordEditor.back()");check(h.js("document.querySelector('#doc-image-menu').hidden&&!!document.querySelector('#doc-image-viewer')").equals("true"),"Back first dismisses image menu, keeps viewer");
  h.js("__failSave=true");click("#doc-image-save");until("!document.querySelector('#doc-image-save').disabled");check(h.js("document.querySelector('#doc-image-save-status').textContent.includes('存储空间不足')").equals("true"),"Storage failure is readable and save remains retryable");
  h.js("__failSave=false;__holdSave=true;document.querySelector('#doc-image-save').click();document.querySelector('#doc-image-save').click()");until("!!window.__deferredSave");check(h.js("__saves.length===2&&document.querySelector('#doc-image-save').disabled").equals("true"),"Repeated taps while saving create only one bridge request");
  h.js("__holdSave=false;__saveNative.call(__deferredSave.a,__deferredSave.p,__deferredSave.id)");until("document.querySelector('#doc-image-save').textContent==='已保存'");check(h.js("__savedUris.length===1&&document.querySelector('#doc-image-save-status').textContent.includes('相册')").equals("true"),"Visible save button reaches real MediaStore and confirms success");h.screenshot("image-saved-to-gallery.png");click("#doc-image-close");
  check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))===__beforeImageSave").equals("true"),"Saving never modifies note body or image placement");
  click("#doc-mode");click("#doc-flow img");until("!!document.querySelector('#doc-image-viewer img')&&document.querySelector('#doc-image-viewer img').naturalWidth>0");h.js("document.querySelector('#doc-image-viewer img').dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true}))");until("!document.querySelector('#doc-image-menu').hidden");click("#doc-image-menu-save");until("__savedUris.length===2");check(true,"Reader context menu saves same local image to gallery");click("#doc-image-close");
  h.js("RecordEditor.previewImage({src:'https://appassets.androidplatform.net/record-media/"+img.getString("id")+".jpg',alt:'生成图片库里的AI插画'})");until("!document.querySelector('#doc-image-save').disabled");click("#doc-image-save");until("__savedUris.length===3");check(true,"AI gallery preview uses same local-save action without inserting into note");
  check(h.js("__saves.every(s=>s.id==='"+img.getString("id")+"'&&Object.keys(s).length===1)").equals("true"),"Only validated local media ID goes to save bridge, no URL/title/prompt/key");
  JSONArray uris=new JSONArray(h.js("__savedUris"));for(int i=0;i<uris.length();i++)exports.add(Uri.parse(uris.getString(i)));
  result.putString("stream","PASS ImageSaveFlowTest: "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable ex){try{h.screenshot("image-save-failure.png");}catch(Exception ignored){}result.putString("stream","FAIL ImageSaveFlowTest after "+passed+": "+ex+"\n");finish(Activity.RESULT_CANCELED,result);}finally{for(Uri uri:exports)try{getTargetContext().getContentResolver().delete(uri,null,null);}catch(Exception ignored){}}}
}
